/* ============================================================
   電卓アプリ スタイルシート
   ============================================================ */

:root {
  --bg-gradient: linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #0f172a 100%);
  --card-bg: rgba(30, 41, 59, 0.85);
  --card-border: rgba(255, 255, 255, 0.1);
  --card-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.08);

  --display-bg: rgba(15, 23, 42, 0.75);
  --display-border: rgba(255, 255, 255, 0.06);

  --btn-num-bg: rgba(51, 65, 85, 0.65);
  --btn-num-hover: rgba(71, 85, 105, 0.8);
  --btn-num-active: rgba(51, 65, 85, 0.95);
  --btn-num-text: #f8fafc;

  --btn-op-bg: #f97316;
  --btn-op-hover: #ea580c;
  --btn-op-active: #c2410c;
  --btn-op-text: #ffffff;

  --btn-action-bg: rgba(71, 85, 105, 0.5);
  --btn-action-hover: rgba(100, 116, 139, 0.65);
  --btn-action-active: rgba(71, 85, 105, 0.85);
  --btn-action-text: #cbd5e1;

  --btn-equal-bg: #3b82f6;
  --btn-equal-hover: #2563eb;
  --btn-equal-active: #1d4ed8;
  --btn-equal-text: #ffffff;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;
  --accent-cyan: #38bdf8;

  --radius-card: 28px;
  --radius-btn: 18px;
  --radius-sm: 10px;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", Monaco, Inconsolata, "Roboto Mono", Consolas, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  margin: 0;
  font-family: var(--font-family);
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow-x: hidden;
}

/* 電卓コンテナ */
.calculator-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 100vh;
  padding: 24px 16px;
}

/* メインカード */
.calculator-card {
  position: relative;
  width: 100%;
  max-width: 380px;
  background: var(--card-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-card);
  box-shadow: var(--card-shadow);
  padding: 24px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 18px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

/* ヘッダーエリア */
.calculator-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4px;
}

.calculator-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* 履歴トグルボタン */
.history-toggle-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  font-size: 0.825rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s ease;
  user-select: none;
}

.history-toggle-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  color: var(--text-main);
  border-color: rgba(255, 255, 255, 0.2);
}

.history-toggle-btn:active {
  transform: scale(0.96);
}

/* ディスプレイパネル */
.display-panel {
  background: var(--display-bg);
  border: 1px solid var(--display-border);
  border-radius: 20px;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-end;
  min-height: 104px;
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.4);
  word-break: break-all;
  overflow: hidden;
}

.display-formula {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  color: var(--text-dim);
  min-height: 1.3em;
  line-height: 1.3;
  margin-bottom: 6px;
  text-align: right;
  letter-spacing: 0.05em;
  width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.display-current {
  font-family: var(--font-mono);
  font-size: 2.25rem;
  font-weight: 600;
  color: var(--text-main);
  line-height: 1.15;
  text-align: right;
  letter-spacing: -0.02em;
  width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* キーパッドグリッド */
.keypad-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

/* 共通ボタンスタイル */
.calc-btn {
  position: relative;
  height: 64px;
  border-radius: var(--radius-btn);
  border: 1px solid transparent;
  font-size: 1.35rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  transition: all 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.2), 0 2px 4px -2px rgba(0, 0, 0, 0.2);
  outline: none;
}

.calc-btn:active {
  transform: scale(0.95) translateY(2px);
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.3);
}

/* 数字ボタン */
.calc-btn-number {
  background: var(--btn-num-bg);
  color: var(--btn-num-text);
  border-color: rgba(255, 255, 255, 0.06);
}

.calc-btn-number:hover {
  background: var(--btn-num-hover);
  border-color: rgba(255, 255, 255, 0.12);
}

.calc-btn-number:active {
  background: var(--btn-num-active);
}

/* 演算子ボタン (+ - × ÷) */
.calc-btn-operator {
  background: var(--btn-op-bg);
  color: var(--btn-op-text);
  font-weight: 600;
  font-size: 1.45rem;
}

.calc-btn-operator:hover {
  background: var(--btn-op-hover);
  box-shadow: 0 0 15px rgba(249, 115, 22, 0.4);
}

.calc-btn-operator:active {
  background: var(--btn-op-active);
}

/* アクションボタン (AC, +/-, %) */
.calc-btn-action {
  background: var(--btn-action-bg);
  color: var(--btn-action-text);
  font-size: 1.15rem;
  font-weight: 600;
  border-color: rgba(255, 255, 255, 0.04);
}

.calc-btn-action:hover {
  background: var(--btn-action-hover);
  color: #ffffff;
}

.calc-btn-action:active {
  background: var(--btn-action-active);
}

/* イコールボタン (=) */
.calc-btn-equal {
  background: var(--btn-equal-bg);
  color: var(--btn-equal-text);
  font-size: 1.5rem;
  font-weight: 600;
}

.calc-btn-equal:hover {
  background: var(--btn-equal-hover);
  box-shadow: 0 0 16px rgba(59, 130, 246, 0.45);
}

.calc-btn-equal:active {
  background: var(--btn-equal-active);
}

/* ゼロボタン (横長レイアウト) */
.calc-btn-zero {
  grid-column: span 2;
  border-radius: var(--radius-btn);
  justify-content: flex-start;
  padding-left: 28px;
}

/* 計算履歴ドロワー */
.history-drawer {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(15, 23, 42, 0.96);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-radius: var(--radius-card);
  padding: 24px;
  display: flex;
  flex-direction: column;
  z-index: 20;
  animation: slideDown 0.25s ease-out;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.history-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 16px;
}

.history-drawer-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.history-clear-btn {
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #fca5a5;
  border-radius: var(--radius-sm);
  padding: 6px 12px;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.history-clear-btn:hover {
  background: rgba(239, 68, 68, 0.25);
  color: #ffffff;
  border-color: rgba(239, 68, 68, 0.5);
}

.history-clear-btn:active {
  transform: scale(0.96);
}

.history-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-right: 4px;
}

/* スクロールバー装飾 */
.history-list::-webkit-scrollbar {
  width: 6px;
}

.history-list::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.02);
  border-radius: 4px;
}

.history-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

.history-list::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.25);
}

.history-item {
  background: rgba(30, 41, 59, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.history-item:hover {
  background: rgba(51, 65, 85, 0.8);
  border-color: rgba(255, 255, 255, 0.15);
  transform: translateX(-2px);
}

.history-item-formula {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--text-muted);
}

.history-item-result {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--accent-cyan);
}

.history-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--text-dim);
  font-size: 0.9rem;
  text-align: center;
  gap: 8px;
}

/* キーボードガイド */
.keyboard-guide {
  margin-top: 18px;
  font-size: 0.775rem;
  color: var(--text-dim);
  text-align: center;
  line-height: 1.6;
  max-width: 380px;
}

.keyboard-guide kbd {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 4px;
  padding: 2px 6px;
  font-family: var(--font-mono);
  font-size: 0.725rem;
  color: var(--text-muted);
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.2);
  margin: 0 2px;
}

/* レスポンシブ対応 (360px以下) */
@media (max-width: 380px) {
  .calculator-card {
    padding: 18px 14px;
    border-radius: 22px;
    gap: 14px;
  }

  .calc-btn {
    height: 56px;
    font-size: 1.2rem;
    border-radius: 14px;
  }

  .calc-btn-operator {
    font-size: 1.3rem;
  }

  .calc-btn-zero {
    padding-left: 22px;
  }

  .display-current {
    font-size: 1.85rem;
  }

  .history-drawer {
    padding: 18px 14px;
  }
}

export type CalcOperator = '+' | '-' | '×' | '÷' | null;

export interface HistoryItem {
  id: string;
  expression: string;
  result: string;
  timestamp: string;
}

export type CalcActionType =
  | 'number'
  | 'operator'
  | 'equal'
  | 'clear'
  | 'toggleSign'
  | 'percent'
  | 'decimal';

export interface ButtonConfig {
  label: string;
  type: CalcActionType;
  value?: string;
  className: string;
  ariaLabel?: string;
}

import { useState, useEffect, useCallback, useId } from 'react';
import { History, X, Trash2, Calculator as CalcIcon } from 'lucide-react';
import { CalcOperator, HistoryItem, ButtonConfig } from './types';
import './index.css';

const formatDisplayNumber = (val: string): string => {
  if (val === 'エラー' || val === 'Infinity' || val === '-Infinity' || val === 'NaN') {
    return 'エラー';
  }
  if (!val) return '0';
  if (val.includes('.')) {
    const [integerPart, decimalPart] = val.split('.');
    const formattedInt = Number(integerPart).toLocaleString('ja-JP');
    return `${formattedInt}.${decimalPart}`;
  }
  const num = Number(val);
  if (isNaN(num)) return val;
  return num.toLocaleString('ja-JP');
};

const roundToPrecision = (num: number): number => {
  return parseFloat(num.toPrecision(12));
};

export default function App() {
  const [currentValue, setCurrentValue] = useState<string>('0');
  const [previousValue, setPreviousValue] = useState<number | null>(null);
  const [operator, setOperator] = useState<CalcOperator>(null);
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [formulaDisplay, setFormulaDisplay] = useState<string>('');
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState<boolean>(false);

  const baseId = useId();

  const handleClear = useCallback(() => {
    setCurrentValue('0');
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setFormulaDisplay('');
  }, []);

  const handleNumberInput = useCallback((numStr: string) => {
    if (waitingForOperand) {
      setCurrentValue(numStr);
      setWaitingForOperand(false);
    } else {
      if (currentValue === '0' || currentValue === 'エラー') {
        setCurrentValue(numStr);
      } else {
        if (currentValue.length < 14) {
          setCurrentValue(currentValue + numStr);
        }
      }
    }
  }, [currentValue, waitingForOperand]);

  const handleDecimal = useCallback(() => {
    if (waitingForOperand) {
      setCurrentValue('0.');
      setWaitingForOperand(false);
      return;
    }
    if (currentValue === 'エラー') {
      setCurrentValue('0.');
      return;
    }
    if (!currentValue.includes('.')) {
      setCurrentValue(currentValue + '.');
    }
  }, [currentValue, waitingForOperand]);

  const handleToggleSign = useCallback(() => {
    if (currentValue === 'エラー' || currentValue === '0') return;
    if (currentValue.startsWith('-')) {
      setCurrentValue(currentValue.slice(1));
    } else {
      setCurrentValue('-' + currentValue);
    }
  }, [currentValue]);

  const handlePercent = useCallback(() => {
    if (currentValue === 'エラー') return;
    const num = parseFloat(currentValue);
    if (isNaN(num)) return;
    const result = roundToPrecision(num / 100);
    setCurrentValue(String(result));
  }, [currentValue]);

  const calculate = useCallback((firstOperand: number, secondOperand: number, op: CalcOperator): number | 'ERROR' => {
    switch (op) {
      case '+':
        return roundToPrecision(firstOperand + secondOperand);
      case '-':
        return roundToPrecision(firstOperand - secondOperand);
      case '×':
        return roundToPrecision(firstOperand * secondOperand);
      case '÷':
        if (secondOperand === 0) return 'ERROR';
        return roundToPrecision(firstOperand / secondOperand);
      default:
        return secondOperand;
    }
  }, []);

  const handleOperator = useCallback((nextOperator: CalcOperator) => {
    if (currentValue === 'エラー') return;
    const currentNum = parseFloat(currentValue);

    if (operator && waitingForOperand) {
      setOperator(nextOperator);
      setFormulaDisplay(`${previousValue} ${nextOperator}`);
      return;
    }

    if (previousValue === null) {
      setPreviousValue(currentNum);
      setFormulaDisplay(`${currentNum} ${nextOperator}`);
    } else if (operator) {
      const result = calculate(previousValue, currentNum, operator);
      if (result === 'ERROR') {
        setCurrentValue('エラー');
        setFormulaDisplay('');
        setPreviousValue(null);
        setOperator(null);
        setWaitingForOperand(false);
        return;
      }
      setCurrentValue(String(result));
      setPreviousValue(result);
      setFormulaDisplay(`${result} ${nextOperator}`);
    }

    setWaitingForOperand(true);
    setOperator(nextOperator);
  }, [currentValue, operator, waitingForOperand, previousValue, calculate]);

  const handleEqual = useCallback(() => {
    if (operator === null || previousValue === null || currentValue === 'エラー') {
      return;
    }

    const currentNum = parseFloat(currentValue);
    const expression = `${previousValue} ${operator} ${currentNum}`;
    const result = calculate(previousValue, currentNum, operator);

    if (result === 'ERROR') {
      setCurrentValue('エラー');
      setFormulaDisplay(`${expression} =`);
      setPreviousValue(null);
      setOperator(null);
      setWaitingForOperand(false);
      return;
    }

    const resultStr = String(result);
    setFormulaDisplay(`${expression} =`);
    setCurrentValue(resultStr);

    const now = new Date();
    const timeFormatted = now.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
    const newHistoryItem: HistoryItem = {
      id: `${baseId}-${Date.now()}-${Math.random()}`,
      expression: `${expression} =`,
      result: resultStr,
      timestamp: timeFormatted,
    };

    setHistory((prev) => [newHistoryItem, ...prev].slice(0, 30));
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(true);
  }, [operator, previousValue, currentValue, calculate, baseId]);

  const handleHistorySelect = useCallback((item: HistoryItem) => {
    setCurrentValue(item.result);
    setFormulaDisplay(item.expression);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(true);
    setShowHistory(false);
  }, []);

  const clearHistory = useCallback(() => {
    setHistory([]);
  }, []);

  // PCキーボード入力対応
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const { key } = event;

      if (/^[0-9]$/.test(key)) {
        event.preventDefault();
        handleNumberInput(key);
      } else if (key === '.') {
        event.preventDefault();
        handleDecimal();
      } else if (key === '+') {
        event.preventDefault();
        handleOperator('+');
      } else if (key === '-') {
        event.preventDefault();
        handleOperator('-');
      } else if (key === '*') {
        event.preventDefault();
        handleOperator('×');
      } else if (key === '/') {
        event.preventDefault();
        handleOperator('÷');
      } else if (key === 'Enter' || key === '=') {
        event.preventDefault();
        handleEqual();
      } else if (key === 'Escape') {
        event.preventDefault();
        handleClear();
      } else if (key === 'Backspace') {
        event.preventDefault();
        if (!waitingForOperand && currentValue !== 'エラー') {
          if (currentValue.length > 1) {
            setCurrentValue(currentValue.slice(0, -1));
          } else {
            setCurrentValue('0');
          }
        }
      } else if (key === '%') {
        event.preventDefault();
        handlePercent();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [
    handleNumberInput,
    handleDecimal,
    handleOperator,
    handleEqual,
    handleClear,
    handlePercent,
    waitingForOperand,
    currentValue,
  ]);

  const buttons: ButtonConfig[] = [
    {
      label: currentValue !== '0' || previousValue !== null ? 'C' : 'AC',
      type: 'clear',
      className: 'calc-btn calc-btn-action',
      ariaLabel: 'クリア',
    },
    {
      label: '+/-',
      type: 'toggleSign',
      className: 'calc-btn calc-btn-action',
      ariaLabel: '符号反転',
    },
    {
      label: '%',
      type: 'percent',
      className: 'calc-btn calc-btn-action',
      ariaLabel: 'パーセント',
    },
    {
      label: '÷',
      type: 'operator',
      value: '÷',
      className: 'calc-btn calc-btn-operator',
      ariaLabel: '割り算',
    },
    {
      label: '7',
      type: 'number',
      value: '7',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '7',
    },
    {
      label: '8',
      type: 'number',
      value: '8',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '8',
    },
    {
      label: '9',
      type: 'number',
      value: '9',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '9',
    },
    {
      label: '×',
      type: 'operator',
      value: '×',
      className: 'calc-btn calc-btn-operator',
      ariaLabel: '掛け算',
    },
    {
      label: '4',
      type: 'number',
      value: '4',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '4',
    },
    {
      label: '5',
      type: 'number',
      value: '5',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '5',
    },
    {
      label: '6',
      type: 'number',
      value: '6',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '6',
    },
    {
      label: '-',
      type: 'operator',
      value: '-',
      className: 'calc-btn calc-btn-operator',
      ariaLabel: '引き算',
    },
    {
      label: '1',
      type: 'number',
      value: '1',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '1',
    },
    {
      label: '2',
      type: 'number',
      value: '2',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '2',
    },
    {
      label: '3',
      type: 'number',
      value: '3',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '3',
    },
    {
      label: '+',
      type: 'operator',
      value: '+',
      className: 'calc-btn calc-btn-operator',
      ariaLabel: '足し算',
    },
    {
      label: '0',
      type: 'number',
      value: '0',
      className: 'calc-btn calc-btn-number calc-btn-zero',
      ariaLabel: '0',
    },
    {
      label: '.',
      type: 'decimal',
      className: 'calc-btn calc-btn-number',
      ariaLabel: '小数点',
    },
    {
      label: '=',
      type: 'equal',
      className: 'calc-btn calc-btn-equal',
      ariaLabel: '計算実行',
    },
  ];

  const handleButtonClick = (btn: ButtonConfig) => {
    switch (btn.type) {
      case 'clear':
        handleClear();
        break;
      case 'toggleSign':
        handleToggleSign();
        break;
      case 'percent':
        handlePercent();
        break;
      case 'operator':
        if (btn.value) {
          handleOperator(btn.value as CalcOperator);
        }
        break;
      case 'number':
        if (btn.value) {
          handleNumberInput(btn.value);
        }
        break;
      case 'decimal':
        handleDecimal();
        break;
      case 'equal':
        handleEqual();
        break;
      default:
        break;
    }
  };

  return (
    <main className="calculator-container">
      <div className="calculator-card">
        {/* ヘッダー */}
        <header className="calculator-header">
          <div className="calculator-title">
            <CalcIcon size={20} />
            <span>高機能電卓</span>
          </div>
          <button
            type="button"
            className="history-toggle-btn"
            onClick={() => setShowHistory(!showHistory)}
            aria-label="計算履歴を表示"
          >
            <History size={16} />
            <span>履歴 ({history.length})</span>
          </button>
        </header>

        {/* ディスプレイパネル */}
        <section className="display-panel" aria-live="polite">
          <div className="display-formula">
            {formulaDisplay || '\u00A0'}
          </div>
          <div className="display-current">
            {formatDisplayNumber(currentValue)}
          </div>
        </section>

        {/* キーパッドグリッド */}
        <div className="keypad-grid">
          {buttons.map((btn) => (
            <button
              key={`${btn.type}-${btn.label}`}
              type="button"
              className={btn.className}
              onClick={() => handleButtonClick(btn)}
              aria-label={btn.ariaLabel || btn.label}
            >
              {btn.label}
            </button>
          ))}
        </div>

        {/* 計算履歴ドロワー */}
        {showHistory && (
          <aside className="history-drawer">
            <div className="history-drawer-header">
              <div className="history-drawer-title">
                <History size={18} />
                <span>計算履歴</span>
              </div>
              <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                {history.length > 0 && (
                  <button
                    type="button"
                    className="history-clear-btn"
                    onClick={clearHistory}
                    aria-label="履歴を全消去"
                  >
                    <Trash2 size={13} style={{ display: 'inline', marginRight: '4px', verticalAlign: 'middle' }} />
                    消去
                  </button>
                )}
                <button
                  type="button"
                  className="history-toggle-btn"
                  onClick={() => setShowHistory(false)}
                  aria-label="履歴パネルを閉じる"
                  style={{ padding: '6px 8px' }}
                >
                  <X size={16} />
                </button>
              </div>
            </div>

            {history.length === 0 ? (
              <div className="history-empty">
                <History size={32} style={{ opacity: 0.4 }} />
                <span>計算履歴がありません</span>
              </div>
            ) : (
              <div className="history-list">
                {history.map((item) => (
                  <div
                    key={item.id}
                    className="history-item"
                    onClick={() => handleHistorySelect(item)}
                    role="button"
                    tabIndex={0}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        handleHistorySelect(item);
                      }
                    }}
                    title="クリックしてこの計算結果を再利用"
                  >
                    <div className="history-item-formula">{item.expression}</div>
                    <div className="history-item-result">{item.result}</div>
                  </div>
                ))}
              </div>
            )}
          </aside>
        )}
      </div>

      {/* キーボードガイド */}
      <footer className="keyboard-guide">
        <p>
          キーボード操作対応: <kbd>0-9</kbd> 数字, <kbd>+</kbd> <kbd>-</kbd> <kbd>*</kbd> <kbd>/</kbd> 演算子, <kbd>Enter</kbd> 計算, <kbd>Esc</kbd> クリア, <kbd>Backspace</kbd> 1文字削除
        </p>
      </footer>
    </main>
  );
}
